uniform float flash_rate : 0.05 .. 2.0 = 0.3;
uniform float flash_duration : 0.01 .. 0.2 = 0.05;
uniform float cloud_speed : 0.1 .. 2.0 = 0.5;
uniform float cloud_density : 0.1 .. 1.0 = 0.7;
uniform vec3 cloud_color : color = 0.05, 0.05, 0.08;
uniform vec3 flash_color : color = 1.0, 0.95, 0.85;
uniform float ambient_glow : 0.0 .. 0.3 = 0.05;

state fixed flash_phase;
state fixed flash_timer;
state fixed cloud_phase;
state bool flash_active;
state int flash_led_start;
state int flash_led_end;

void update() {
  cloud_phase = fract(cloud_phase + fixed(dt * cloud_speed * 0.2));

  if (!flash_active) {
    flash_phase = fract(flash_phase + fixed(dt * flash_rate));
    if (flash_phase < fixed(dt * flash_rate)) {
      flash_active = true;
      flash_timer = fixed(flash_duration);
      flash_led_start = int(hash(float(frame)) * float(led.count));
      flash_led_end = int(hash(float(frame) * 3.0) * float(led.count));
      if (flash_led_start > flash_led_end) {
        int tmp = flash_led_start;
        flash_led_start = flash_led_end;
        flash_led_end = tmp;
      }
    }
  } else {
    flash_timer = flash_timer - fixed(dt);
    if (flash_timer <= fixed(0.0)) {
      flash_active = false;
      flash_phase = fixed(0.0);
    }
  }
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed y = fixed(led.pos.y);
  fixed idx = fixed(led.idx);
  fixed count = fixed(led.count);

  fixed cloud_noise = sin(s * fixed(8.0) + cloud_phase) * fixed(0.5) + fixed(0.5);
  fixed cloud_mask = step(cloud_noise, fixed(cloud_density));

  vec3 base = vec3(cloud_color.x, cloud_color.y, cloud_color.z) * float(cloud_mask) + vec3(ambient_glow);

  if (flash_active) {
    fixed flash_progress = flash_timer / fixed(flash_duration);
    fixed flash_intensity = flash_progress * flash_progress;

    fixed led_norm = idx / count;
    fixed flash_start_norm = fixed(flash_led_start) / count;
    fixed flash_end_norm = fixed(flash_led_end) / count;

    fixed in_flash = step(flash_start_norm, led_norm) * step(led_norm, flash_end_norm);
    fixed vertical_falloff = fixed(1.0) - abs(y / fixed(0.15));
    vertical_falloff = clamp(vertical_falloff, fixed(0.0), fixed(1.0));

    fixed total_flash = flash_intensity * in_flash * vertical_falloff * fixed(0.7) + flash_intensity * fixed(0.3);

    vec3 flash_rgb = vec3(flash_color.x, flash_color.y, flash_color.z) * float(total_flash);
    return base + flash_rgb;
  }

  return base;
}
